function score(r){var certs=r[0],cont=r[1],tg=r[3],cards=r[4],js=r[5],ws=r[6],items=[],pass=0,total=0,exp30=[],bad=[];
 certs.forEach(function(c){var st=certStat(c,cont),P=(PRE[c.type]||PRE.custom)[0]+(c.process?' '+c.process:'');total++;if(st.bad){bad.push(c);items.push({s:'r',t:c.worker+': '+P+' '+st.txt})}else{pass++;if(st.days<=30){exp30.push(c);items.push({s:st.s,t:c.worker+': '+P+' '+st.txt})}else if(c.type=='weld'&&st.days<=60)items.push({s:'y',t:c.worker+': '+P+' continuity at risk ('+st.basis+', runs out '+dl(st.exp)+')'})}});
 js.filter(function(j){return j.status!='Done'}).forEach(function(j){total++;var l=tg.filter(function(t){return t.jobId==j.id}).sort(function(a,b){return b.date-a.date})[0];if(l&&workdays(l.date,Date.now())<=10&&l.att.every(function(a){return a.signedAt}))pass++;else items.push({s:'r',t:'Tailgate '+(l?(workdays(l.date,Date.now())>10?'over 10 working days old':'sign-offs incomplete'):'missing')+': '+j.name})});
 var lw=wk0(Date.now())-7*DAY;ws.forEach(function(w){if(!r[2].some(function(p){return p.worker==w.name&&p.in.ts>=lw&&p.in.ts<lw+7*DAY}))return;total++;var c=cards.filter(function(c){return c.worker==w.name&&c.weekStart==lw&&c.status!='Resubmitted'}).sort(function(a,b){return b.submittedAt-a.submittedAt})[0];if(c&&c.status=='Approved')pass++;else items.push({s:'y',t:w.name+': last week\'s time card '+(c?c.status.toLowerCase():'not submitted')})});
 return{pct:total?Math.round(pass/total*100):100,pass:pass,total:total,items:items,exp30:exp30,bad:bad}}
