 if(navigator.canShare&&files.length&&navigator.canShare({files:files}))return navigator.share({title:'Time card '+c.worker,text:txt,files:files}).catch(function(){});
 if(navigator.share)return navigator.share({title:'Time card '+c.worker,text:txt}).catch(function(){});
